// ฟังก์ชันสร้าง PromptPay EMVCo QR Code สำหรับพร้อมเพย์ 063-880-1739 / KBank 185-2-97237-4 (นาย ธนภูมิ รักษี)
const OFFICIAL_KPLUS_QR_IMAGE = "data:image/webp;base64,";

// ฟังก์ชันตรวจสอบสลิปผ่านเซิร์ฟเวอร์หลังบ้าน /api/verify-slip (ปลอดภัย 100% ไม่เปิดเผย API Key หน้าบ้าน)
const verifySlipWithSlipOK = async (imageBase64Data, expectedAmount, metadata = {}) => {
  let cleanBase64 = imageBase64Data;
  if (cleanBase64.includes(',')) {
    cleanBase64 = cleanBase64.split(',')[1];
  }

  try {
    let apiEndpoint = '/api/verify-slip';
    if (typeof window !== 'undefined' && window.location && window.location.origin && window.location.origin.startsWith('http')) {
      apiEndpoint = `${window.location.origin}/api/verify-slip`;
    }

    const response = await fetch(apiEndpoint, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        imageBase64: cleanBase64,
        expectedAmount: expectedAmount,
        ...metadata
      }),
    });

    const data = await response.json().catch(() => ({}));

    if (response.ok && data.success) {
      return data;
    } else {
      return {
        success: false,
        message: data.message || 'สลิปไม่ถูกต้อง ยอดเงินไม่ตรง หรือไม่ได้โอนเข้าบัญชีร้าน'
      };
    }
  } catch (backendErr) {
    console.error('Call /api/verify-slip error:', backendErr);
    return {
      success: false,
      message: 'ไม่สามารถเชื่อมต่อเซิร์ฟเวอร์ตรวจสอบสลิปได้ กรุณาลองใหม่อีกครั้ง (' + backendErr.message + ')'
    };
  }
};

// ฟังก์ชันรับซองของขวัญ TrueMoney Wallet อัตโนมัติ (/api/redeem-voucher)
const redeemTrueMoneyVoucher = async (voucherUrl, expectedAmount, metadata = {}) => {
  try {
    let apiEndpoint = '/api/redeem-voucher';
    if (typeof window !== 'undefined' && window.location && window.location.origin && window.location.origin.startsWith('http')) {
      apiEndpoint = `${window.location.origin}/api/redeem-voucher`;
    }

    const response = await fetch(apiEndpoint, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        voucherUrl,
        expectedAmount,
        ...metadata
      }),
    });

    const data = await response.json().catch(() => ({}));

    if (response.ok && data.success) {
      return { success: true, data: data.data, message: data.message };
    } else {
      return {
        success: false,
        cloudflareBlocked: !!data.cloudflareBlocked,
        voucherUrl: data.voucherUrl || voucherUrl,
        message: data.message || 'ไม่สามารถรับซองของขวัญได้'
      };
    }
  } catch (err) {
    console.error('Call /api/redeem-voucher error:', err);
    return { success: false, message: 'เกิดข้อผิดพลาดในการเชื่อมต่อเซิร์ฟเวอร์ (' + err.message + ')' };
  }
};

const generatePromptPayQrPayload = (amount) => {
  const crc16 = (data) => {
    let crc = 0xFFFF;
    for (let i = 0; i < data.length; i++) {
      crc ^= data.charCodeAt(i) << 8;
      for (let j = 0; j < 8; j++) {
        if ((crc & 0x8000) !== 0) {
          crc = ((crc << 1) ^ 0x1021) & 0xFFFF;
        } else {
          crc = (crc << 1) & 0xFFFF;
        }
      }
    }
    return crc.toString(16).toUpperCase().padStart(4, '0');
  };

  // เบอร์พร้อมเพย์ 063-880-1739 -> 0066638801739
  const ppTarget = '01130066638801739';
  const merchantInfo = `0016A000000677010111${ppTarget}`;
  const tag29 = `29${merchantInfo.length.toString().padStart(2, '0')}${merchantInfo}`;

  if (!amount || amount <= 0) {
    const rawStatic = `000201010211${tag29}5802TH53037646304`;
    return rawStatic + crc16(rawStatic);
  }
  const amtStr = parseFloat(amount).toFixed(2);
  const amtTag = `54${amtStr.length.toString().padStart(2, '0')}${amtStr}`;
  const raw = `000201010212${tag29}5802TH5303764${amtTag}6304`;
  return raw + crc16(raw);
};

